def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    # Count total defections
    total_def = opp.count('D')
    total_coop = n - total_def

    # Count recent opponent behavior (last 10)
    window = min(10, n)
    recent = opp[-window:]
    recent_def = recent.count('D')
    recent_coop = window - recent_def

    # Count trailing defection streak
    tail_def = 0
    for a in reversed(opp):
        if a == 'D':
            tail_def += 1
        else:
            break

    # Count trailing mutual cooperation streak
    tail_cc = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'C' and me[i] == 'C':
            tail_cc += 1
        else:
            break

    # Terminal defection when opponent is very cooperative
    if n >= 90:
        # Exploit: opponent rarely defects, defect to gain
        if total_def <= 3:
            return 'D'
        if recent_def == 0:
            return 'D'

    # If opponent defected heavily, defect
    if recent_def * 2 > window:
        return 'D'

    # If trailing defection streak of 2+, retaliate
    if tail_def >= 2:
        return 'D'

    # If opponent just defected (single)
    if opp[-1] == 'D':
        # Verify it's isolated - if overall highly cooperative, retaliate once
        if total_coop * 3 >= n * 2:
            # mostly cooperative: retaliate once but then forgive
            if n >= 2 and opp[-2] == 'C':
                return 'D'
            return 'D'
        # mixed: defect
        return 'D'

    # Opponent cooperated last
    # If we are in a long mutual cooperation, cooperate
    if tail_cc >= 2:
        # occasional probe, but rarely to avoid costly retaliation
        if n >= 20 and n % 25 == 0 and total_def <= 2:
            return 'D'
        return 'C'

    # Opponent cooperated but we may have defected
    if me[-1] == 'D':
        # Reciprocate with cooperation, occasionally exploit
        if total_def <= 1 and n >= 15:
            if rng.random() < 0.15:
                return 'D'
        return 'C'

    # Default: cooperate against cooperative opponents
    if total_def == 0:
        return 'C'

    if total_coop * 3 >= n * 2:
        return 'C'

    # Mixed opponent: be cautious
    if recent_def == 0:
        return 'C'

    return 'C'
